(function () {
  const root = document.querySelector("#bvcV7Header");
  if (!root) return;

  const openBtn = root.querySelector(".bvc-v7-hamburger");
  const closeBtn = root.querySelector(".bvc-v7-close");
  const backdrop = root.querySelector(".bvc-v7-backdrop");
  const mobileMenu = root.querySelector(".bvc-v7-mobile-menu");

  function openMenu() {
    document.body.classList.add("bvc-v7-menu-open");
    if (openBtn) openBtn.setAttribute("aria-expanded", "true");
  }

  function closeMenu() {
    document.body.classList.remove("bvc-v7-menu-open");
    if (openBtn) openBtn.setAttribute("aria-expanded", "false");
  }

  if (openBtn) openBtn.addEventListener("click", openMenu);
  if (closeBtn) closeBtn.addEventListener("click", closeMenu);
  if (backdrop) backdrop.addEventListener("click", closeMenu);

  document.addEventListener("keydown", function (event) {
    if (event.key === "Escape") closeMenu();
  });

  if (mobileMenu) {
    const parentItems = mobileMenu.querySelectorAll("li.menu-item-has-children");

    parentItems.forEach(function (item) {
      const directChildren = Array.from(item.children);
      const link = directChildren.find(function (child) {
        return child.tagName && child.tagName.toLowerCase() === "a";
      });
      const submenu = directChildren.find(function (child) {
        return child.tagName && child.tagName.toLowerCase() === "ul";
      });

      if (!link || !submenu || directChildren.some(function (child) {
        return child.classList && child.classList.contains("bvc-v7-sub-toggle");
      })) return;

      const button = document.createElement("button");
      button.type = "button";
      button.className = "bvc-v7-sub-toggle";
      button.setAttribute("aria-label", "Toggle submenu");
      button.innerHTML = "⌄";

      link.insertAdjacentElement("afterend", button);

      button.addEventListener("click", function (event) {
        event.preventDefault();
        event.stopPropagation();

        const siblings = Array.from(item.parentElement.children).filter(function (child) {
          return child !== item;
        });

        siblings.forEach(function (sibling) {
          sibling.classList.remove("is-open");
        });

        item.classList.toggle("is-open");
      });
    });
  }
})();

(function () {
  const BVC_HERO_SLIDES = [
    "https://bvcits.edu.in/wp-content/uploads/2026/07/Image-1.jpg-1.jpeg",
    "https://bvcits.edu.in/wp-content/uploads/2026/06/TCS-BVCITS-PLACEMENT.png",
    "https://bvcits.edu.in/wp-content/uploads/2026/06/COGNIGENT-BVCITS-PLACEMENT.png",
    "https://bvcits.edu.in/wp-content/uploads/2026/06/MOLDTEK-BVCITS-PLACEMENT.png",
    "https://bvcits.edu.in/wp-content/uploads/2026/06/KEKA-BVCITS-PLACEMENT.png",
    "https://bvcits.edu.in/wp-content/uploads/2025/07/h4-scaled.jpg",
    "https://bvcits.edu.in/wp-content/uploads/2026/06/file_000000004114720b8e02514d6c018b9f.png"
  ];

  const AUTOPLAY_TIME = 5000;

  const root = document.querySelector(".bvc-next-hero");
  if (!root) return;

  const track = root.querySelector("#bvcNextHeroTrack");
  const dotsWrap = root.querySelector("#bvcNextHeroDots");
  const prevBtn = root.querySelector(".bvc-next-prev");
  const nextBtn = root.querySelector(".bvc-next-next");
  const progress = root.querySelector("#bvcNextHeroProgress");
  const slider = root.querySelector("#bvcNextHeroSlider");
  const pop = root.querySelector(".bvc-next-placement-pop");
  const popClose = root.querySelector(".bvc-next-placement-pop button");

  let current = 0;
  let timer = null;
  let startX = 0;

  function renderSlides() {
    track.innerHTML = BVC_HERO_SLIDES.map(function (src, index) {
      return `




      `;
    }).join("");

    dotsWrap.innerHTML = BVC_HERO_SLIDES.map(function (_, index) {
      return `


      `;
    }).join("");

    dotsWrap.querySelectorAll(".bvc-next-dot").forEach(function (dot) {
      dot.addEventListener("click", function () {
        goTo(Number(this.dataset.index));
        restartAutoplay();
      });
    });

    updateSlider();
    startAutoplay();
  }

  function updateSlider() {
    track.style.transform = "translateX(-" + current * 100 + "%)";

    dotsWrap.querySelectorAll(".bvc-next-dot").forEach(function (dot, index) {
      dot.classList.toggle("is-active", index === current);
    });

    restartProgress();
  }

  function restartProgress() {
    progress.classList.remove("is-running");
    void progress.offsetWidth;
    progress.classList.add("is-running");
  }

  function goTo(index) {
    current = (index + BVC_HERO_SLIDES.length) % BVC_HERO_SLIDES.length;
    updateSlider();
  }

  function nextSlide() {
    goTo(current + 1);
  }

  function prevSlide() {
    goTo(current - 1);
  }

  function startAutoplay() {
    stopAutoplay();
    if (BVC_HERO_SLIDES.length <= 1) return;
    timer = setInterval(nextSlide, AUTOPLAY_TIME);
    restartProgress();
  }

  function stopAutoplay() {
    if (timer) {
      clearInterval(timer);
      timer = null;
    }
  }

  function restartAutoplay() {
    stopAutoplay();
    startAutoplay();
  }

  prevBtn.addEventListener("click", function () {
    prevSlide();
    restartAutoplay();
  });

  nextBtn.addEventListener("click", function () {
    nextSlide();
    restartAutoplay();
  });

  slider.addEventListener("mouseenter", stopAutoplay);
  slider.addEventListener("mouseleave", startAutoplay);

  slider.addEventListener("touchstart", function (event) {
    startX = event.touches[0].clientX;
    stopAutoplay();
  }, { passive: true });

  slider.addEventListener("touchend", function (event) {
    const endX = event.changedTouches[0].clientX;
    const diff = startX - endX;

    if (Math.abs(diff) > 45) {
      diff > 0 ? nextSlide() : prevSlide();
    }

    startAutoplay();
  });

  if (popClose && pop) {
    popClose.addEventListener("click", function () {
      pop.style.display = "none";
    });
  }

  document.addEventListener("visibilitychange", function () {
    document.hidden ? stopAutoplay() : startAutoplay();
  });

  renderSlides();
})();

(function () {
  const root = document.querySelector(".bvc-courses-studio");
  if (!root) return;

  const tabs = root.querySelectorAll(".bvc-course-nav-item");
  const panels = root.querySelectorAll(".bvc-course-panel");
  const type = root.querySelector("#bvcCourseType");
  const heading = root.querySelector("#bvcCourseHeading");
  const desc = root.querySelector("#bvcCourseDesc");

  const copy = {
    ug: {
      type: "Under Graduate Course",
      heading: "B.Tech Programmes",
      desc: "Four-year engineering programmes with strong fundamentals, practical learning and industry-oriented career preparation."
    },
    degree: {
      type: "Under Graduate Degree",
      heading: "Degree Programmes",
      desc: "Professional undergraduate programmes for students interested in management, business and computer application careers."
    },
    pg: {
      type: "Post Graduate Course",
      heading: "Post Graduate Programmes",
      desc: "Advanced programmes for technical specialization, management growth and professional computing careers."
    },
    diploma: {
      type: "Polytechnic",
      heading: "Diploma Courses",
      desc: "Practical, skill-focused diploma programmes for early technical career pathways and hands-on learning."
    }
  };

  tabs.forEach(function (tab) {
    tab.addEventListener("click", function () {
      const target = tab.getAttribute("data-tab");

      tabs.forEach(function (item) {
        item.classList.remove("active");
        item.setAttribute("aria-selected", "false");
      });

      panels.forEach(function (panel) {
        panel.classList.remove("active");
      });

      tab.classList.add("active");
      tab.setAttribute("aria-selected", "true");
      root.querySelector('[data-panel="' + target + '"]').classList.add("active");

      type.textContent = copy[target].type;
      heading.textContent = copy[target].heading;
      desc.textContent = copy[target].desc;
    });
  });
})();

(function () {
  const WP_SITE = "https://bvcits.edu.in";
  const CATEGORY_SLUG = "scroll";
  const POSTS_COUNT = 12;
  const AUTO_SCROLL_TIME = 2600;

  const API_BASE = WP_SITE.replace(/\/$/, "") + "/wp-json/wp/v2";

  const section = document.querySelector(".bvc-happenings-section");
  if (!section) return;

  const track = section.querySelector("#bvcHappeningsTrack");
  const dots = section.querySelector("#bvcHappeningsDots");
  const prevBtn = section.querySelector(".bvc-happenings-btn-prev");
  const nextBtn = section.querySelector(".bvc-happenings-btn-next");

  let posts = [];
  let currentIndex = 0;
  let visibleCards = getVisibleCards();
  let autoScrollInterval = null;

  function getVisibleCards() {
    const width = window.innerWidth;
    if (width <= 680) return 1;
    if (width <= 1100) return 2;
    return 3;
  }

  function cleanText(html) {
    const div = document.createElement("div");
    div.innerHTML = html || "";
    return div.textContent || div.innerText || "";
  }

  function formatDate(dateString) {
    const date = new Date(dateString);
    return date.toLocaleDateString("en-IN", {
      day: "2-digit",
      month: "short",
      year: "numeric"
    });
  }

  function getFeaturedImage(post) {
    const media = post._embedded && post._embedded["wp:featuredmedia"];

    if (media && media[0]) {
      return (
        media[0].media_details?.sizes?.full?.source_url ||
        media[0].media_details?.sizes?.large?.source_url ||
        media[0].media_details?.sizes?.medium_large?.source_url ||
        media[0].source_url ||
        ""
      );
    }

    return "";
  }

  function getMaxIndex() {
    return Math.max(0, posts.length - visibleCards);
  }

  function renderLoading() {
    visibleCards = getVisibleCards();

    track.innerHTML = Array.from({ length: visibleCards }).map(function () {
      return `














      `;
    }).join("");
  }

  function renderCards() {
    visibleCards = getVisibleCards();
    currentIndex = Math.min(currentIndex, getMaxIndex());

    track.innerHTML = posts.map(function (post) {
      const title = cleanText(post.title && post.title.rendered);
      const image = getFeaturedImage(post);
      const link = post.link || "#";
      const date = formatDate(post.date);

      return `




              ${
                image
                  ? `<img decoding="async" class="bvc-happenings-image" src="${image}" alt="${title.replace(/"/g, "'")}" loading="lazy">`
                  : `
`
              }







${title}


                ${date}

                  Read








      `;
    }).join("");

    updateSlider();
    renderDots();
    startAutoScroll();
  }

  function updateSlider() {
    const firstCard = track.querySelector(".bvc-happenings-card");
    if (!firstCard) return;

    const gap = parseFloat(getComputedStyle(track).gap) || 28;
    const cardWidth = firstCard.getBoundingClientRect().width;
    const moveX = currentIndex * (cardWidth + gap);

    track.style.transform = "translateX(-" + moveX + "px)";
  }

  function renderDots() {
    const totalDots = getMaxIndex() + 1;

    dots.innerHTML = Array.from({ length: totalDots }).map(function (_, index) {
      return `


      `;
    }).join("");

    dots.querySelectorAll(".bvc-happenings-dot").forEach(function (dot) {
      dot.addEventListener("click", function () {
        stopAutoScroll();
        currentIndex = Number(this.dataset.index);
        updateSlider();
        renderDots();
        startAutoScroll();
      });
    });
  }

  function goNext() {
    currentIndex = currentIndex >= getMaxIndex() ? 0 : currentIndex + 1;
    updateSlider();
    renderDots();
  }

  function goPrev() {
    currentIndex = currentIndex <= 0 ? getMaxIndex() : currentIndex - 1;
    updateSlider();
    renderDots();
  }

  function startAutoScroll() {
    stopAutoScroll();
    if (posts.length <= visibleCards) return;

    autoScrollInterval = setInterval(function () {
      goNext();
    }, AUTO_SCROLL_TIME);
  }

  function stopAutoScroll() {
    if (autoScrollInterval) {
      clearInterval(autoScrollInterval);
      autoScrollInterval = null;
    }
  }

  async function getCategoryId() {
    const response = await fetch(API_BASE + "/categories?slug=" + CATEGORY_SLUG + "&per_page=1");
    const categories = await response.json();
    return categories && categories[0] ? categories[0].id : null;
  }

  async function fetchPosts() {
    renderLoading();

    try {
      const categoryId = await getCategoryId();

      const postsUrl = categoryId
        ? API_BASE + "/posts?categories=" + categoryId + "&per_page=" + POSTS_COUNT + "&_embed=1&orderby=date&order=desc"
        : API_BASE + "/posts?per_page=" + POSTS_COUNT + "&_embed=1&orderby=date&order=desc";

      const response = await fetch(postsUrl);

      if (!response.ok) {
        throw new Error("WordPress API error");
      }

      posts = await response.json();

      if (!Array.isArray(posts) || posts.length === 0) {
        throw new Error("No posts found");
      }

      renderCards();
    } catch (error) {
      track.innerHTML = `


          Posts could not be loaded. Please check the WordPress category slug, REST API, or CORS settings.

      `;
      dots.innerHTML = "";
    }
  }

  prevBtn.addEventListener("click", function () {
    stopAutoScroll();
    goPrev();
    startAutoScroll();
  });

  nextBtn.addEventListener("click", function () {
    stopAutoScroll();
    goNext();
    startAutoScroll();
  });

  track.addEventListener("mouseenter", stopAutoScroll);
  track.addEventListener("mouseleave", startAutoScroll);

  window.addEventListener("resize", function () {
    visibleCards = getVisibleCards();
    currentIndex = Math.min(currentIndex, getMaxIndex());
    updateSlider();
    renderDots();
    startAutoScroll();
  });

  fetchPosts();
})();

(function () {
  const root = document.querySelector(".bvc-placement-signature");
  if (!root) return;

  const revealItems = root.querySelectorAll(".bvc-ps-reveal");
  const counters = root.querySelectorAll(".bvc-ps-count[data-count]");

  function animateCounter(el) {
    if (el.dataset.done === "true") return;

    const target = parseInt(el.getAttribute("data-count"), 10);
    const suffix = el.getAttribute("data-suffix") || "";
    const duration = 1300;
    const startTime = performance.now();

    el.dataset.done = "true";

    function update(now) {
      const progress = Math.min((now - startTime) / duration, 1);
      const eased = 1 - Math.pow(1 - progress, 3);
      const value = Math.round(target * eased);

      el.textContent = value.toLocaleString("en-IN") + suffix;

      if (progress < 1) {
        requestAnimationFrame(update);
      } else {
        el.textContent = target.toLocaleString("en-IN") + suffix;
      }
    }

    requestAnimationFrame(update);
  }

  if ("IntersectionObserver" in window) {
    const revealObserver = new IntersectionObserver(function (entries) {
      entries.forEach(function (entry, index) {
        if (entry.isIntersecting) {
          setTimeout(function () {
            entry.target.classList.add("is-visible");
          }, index * 90);
        }
      });
    }, { threshold: 0.16 });

    revealItems.forEach(function (item) {
      revealObserver.observe(item);
    });

    const counterObserver = new IntersectionObserver(function (entries, obs) {
      entries.forEach(function (entry) {
        if (entry.isIntersecting) {
          animateCounter(entry.target);
          obs.unobserve(entry.target);
        }
      });
    }, { threshold: 0.45 });

    counters.forEach(function (counter) {
      counterObserver.observe(counter);
    });
  } else {
    revealItems.forEach(function (item) {
      item.classList.add("is-visible");
    });

    counters.forEach(animateCounter);
  }
})();

(function () {
  const root = document.querySelector(".bvc-pro-placement");
  if (!root) return;

  const revealItems = root.querySelectorAll(".bvc-pro-reveal");

  if ("IntersectionObserver" in window) {
    const observer = new IntersectionObserver(function (entries) {
      entries.forEach(function (entry, index) {
        if (entry.isIntersecting) {
          setTimeout(function () {
            entry.target.classList.add("is-visible");
          }, index * 90);
          observer.unobserve(entry.target);
        }
      });
    }, { threshold: 0.18 });

    revealItems.forEach(function (item) {
      observer.observe(item);
    });
  } else {
    revealItems.forEach(function (item) {
      item.classList.add("is-visible");
    });
  }
})();

